import fs from 'node:fs';
import path from 'node:path';
import cp from 'node:child_process';
import { performance } from 'node:perf_hooks';
import { pathToFileURL } from 'node:url';
const temporary = path.dirname(import.meta.filename);
const fixture = path.join(temporary,'fixture');
const root = '/home/ubuntu/github/keelson';
function run(cmd,args,options={}) { const r=cp.spawnSync(cmd,args,{cwd:fixture,encoding:'utf8',...options});if(r.status!==0)throw new Error(r.stderr);return r.stdout; }
if(!fs.existsSync(fixture)) {
 fs.mkdirSync(fixture);for(let i=0;i<5000;i++){const d=path.join(fixture,'src',String(Math.floor(i/100)));fs.mkdirSync(d,{recursive:true});fs.writeFileSync(path.join(d,`f${i}.js`),`export const fixture${i} = ${i};\n`);}
 run('git',['init','-q']);run('git',['add','src']);run('git',['-c','user.name=Diagnostic fixture','-c','user.email=fixture@example.invalid','commit','-qm','fixture']);
 run(process.execPath,[path.join(root,'bin/keelson.js'),'init','--tools','agents','--no-hooks']);
 fs.writeFileSync(path.join(fixture,'.keelson/config.yaml'),'version: 4\ncheck: []\n');
}
const original=path.join(root,'src/commands/status.js');const bundle=path.join(temporary,'status.mjs');
const output={diagnosticOnly:true,sourceCommit:run('git',['rev-parse','HEAD'],{cwd:root}).trim(),observedAt:new Date().toISOString(),modelRunsConcurrent:true,files:5000,cases:{},identicalStatus:true};let reference;
for(const [name,module] of [['original',original],['bundled',bundle]]) {const samples=[];
 for(let i=0;i<5;i++){const start=performance.now();const result=run(process.execPath,['--input-type=module','-e',`const {status}=await import(${JSON.stringify(pathToFileURL(module).href)}); await status({flags:{json:true}},${JSON.stringify(fixture)});`]);samples.push(+(performance.now()-start).toFixed(3));reference??=result;if(result!==reference)output.identicalStatus=false;}
 output.cases[name]=samples;
}
const profileSource=`import fs from 'node:fs';import cp from 'node:child_process';import crypto from 'node:crypto';import {performance} from 'node:perf_hooks';import {syncBuiltinESMExports} from 'node:module';
 const timings={};
 for(const [obj,key,label] of [[cp,'execFileSync','execFileSync'],[fs,'lstatSync','lstat'],[fs,'readFileSync','read'],[crypto,'createHash','createHash']]){const original=obj[key];obj[key]=function(...args){const s=performance.now();try{return original.apply(this,args);}finally{const k=key==='execFileSync'?label+':'+args[1].join(' '):label;const t=timings[k]??={calls:0,ms:0};t.calls++;t.ms+=performance.now()-s;}};}syncBuiltinESMExports();
 const s=performance.now();const {status}=await import(${JSON.stringify(pathToFileURL(original).href)});const imported=performance.now();const stdout=console.log;console.log=()=>{};await status({flags:{json:true}},${JSON.stringify(fixture)});stdout(JSON.stringify({timings,importMs:imported-s,executionMs:performance.now()-imported}));`;
output.instrumented=JSON.parse(run(process.execPath,['--input-type=module','-e',profileSource]));
fs.writeFileSync(path.join(temporary,'whole.json'),JSON.stringify(output,null,2)+'\n');console.log(JSON.stringify(output));
